const fs = require('fs');

const enMetaFixes = {
  'fog-dream': 'Fog clearing in a Korean dream is a powerful good omen; dense fog warns of illness and setbacks. All fog dream scenarios explained with cultural context.',
  'heavy-rain-dream': 'Heavy rain in a Korean dream can signal wealth or warning — everything depends on water clarity and emotional state. Full dream interpretation guide.',
  'lightning-weather-dream': 'Dreaming of lightning in Korean culture? Being struck, thunder with lightning, house hit, pregnancy omens — complete interpretation guide explained.',
  'rain-weather-dream': 'Complete guide to rain dream meaning in Korean tradition. Getting drenched, sudden showers, torrential rain, monsoon, and rainbow — auspicious vs inauspicious.',
  'rainbow-dream': 'Complete guide to rainbow dream meanings in Korean tradition. Vivid, double, broken, and black rainbows — plus rainbow pregnancy dreams all interpreted.',
  'snow-dream': 'Clean white snow is one of the most auspicious Korean dream omens. Heavy snowfall, blizzards, avalanches, and snow-walking — full cultural interpretation.',
  'storm-dream': 'What does a storm dream mean in Korean tradition? House destroyed by typhoon vs. clear skies after rain — full auspicious and inauspicious storm meanings.',
  'thunder-dream': 'Complete guide to thunder dream meanings in Korean interpretation. When thunder signals wealth and fame vs. warning — lightning strike and pregnancy omens.',
  'tornado-dream': 'Tornado dream meaning in Korean interpretation. Surviving, house destroyed, swept away, black tornado, rainbow after storm — auspicious and inauspicious.',
  'typhoon-dream': 'What does a typhoon dream mean in Korean tradition? Surviving a storm, clear skies after a typhoon, house destroyed — complete dream interpretation explained.',
};

const koMetaFixes = {
  // thunder-dream only: 72 → need 80+
  'thunder-dream': '천둥 꿈해몽 완벽 해석. 천둥소리·벼락 맞는 꿈·천둥번개 태몽까지 상황별 길몽·흉몽 의미와 재물운·명성운을 전문가가 총정리해 드립니다.',
};

const changes = {};

Object.entries(enMetaFixes).forEach(([slug, newMeta]) => {
  const path = 'data/content/weather/' + slug + '.json';
  const data = JSON.parse(fs.readFileSync(path, 'utf8'));
  const oldMeta = data.en.metaDescription;

  if (!changes[slug]) changes[slug] = [];

  if (oldMeta !== newMeta) {
    data.en.metaDescription = newMeta;
    changes[slug].push({field: 'en.metaDescription', oldLen: oldMeta.length, newLen: newMeta.length});
  }

  // Apply KO fixes if any
  if (koMetaFixes[slug]) {
    const oldKo = data.ko.metaDescription;
    data.ko.metaDescription = koMetaFixes[slug];
    changes[slug].push({field: 'ko.metaDescription', oldLen: oldKo.length, newLen: koMetaFixes[slug].length});
  }

  // Fix lightning-weather-dream: remove spurious content2 key
  if (slug === 'lightning-weather-dream') {
    data.en.sections.forEach(section => {
      if (section.content2 !== undefined) {
        delete section.content2;
        changes[slug].push({field: 'en.sections[1].content2', issue: 'spurious key removed'});
      }
    });
  }

  fs.writeFileSync(path, JSON.stringify(data, null, 2));
  console.log('Wrote ' + slug);
});

console.log('\\nAll changes:', JSON.stringify(changes, null, 2));
" 2>&1

