  if (enMeta < 120 || enMeta > 160) issues.push(\`en.meta:\${enMeta}\`);
  if (koFaqs < 5) issues.push(\`ko.faqs:\${koFaqs}\`);
  if (enFaqs < 5) issues.push(\`en.faqs:\${enFaqs}\`);
  if (!hasRelatedSlugs) issues.push('no relatedSlugs');
