#!/usr/bin/env node
/**
 * Build public/search-index.json from data/content files.
 * Run after any content changes: node scripts/build-search-index.mjs
 * Also hooked into `npm run build` via package.json prebuild.
 */

import { readFile, writeFile } from "fs/promises";
import { glob } from "glob";

function detectBadge(heading = "") {
  if (heading.includes("길몽") || /auspicious/i.test(heading)) return "auspicious";
  if (heading.includes("흉몽") || /inauspicious/i.test(heading)) return "inauspicious";
  return "neutral";
}

const files = await glob("data/content/**/*.json");
const index = [];

for (const file of files) {
  const raw = await readFile(file, "utf8");
  const data = JSON.parse(raw);

  const slug = data.slug ?? data.seo?.slug;
  const koreanSlug = data.seo?.koreanSlug ?? data.koreanSlug ?? "";
  const titleKo = data.ko?.title ?? "";
  const titleEn = data.en?.title ?? "";
  const tagsKo = data.seo?.naverSEO?.tags ?? [];
  const hero = data.images?.hero ?? null;
  const badgeType = detectBadge(data.ko?.sections?.[0]?.heading ?? "");

  if (!slug) continue;

  index.push({ slug, koreanSlug, titleKo, titleEn, tagsKo, badgeType, hero });
}

// Sort alphabetically by slug for deterministic output
index.sort((a, b) => a.slug.localeCompare(b.slug));

const outPath = "public/search-index.json";
await writeFile(outPath, JSON.stringify(index), "utf8");
console.log(`✅ search-index.json — ${index.length} entries → ${outPath}`);

"use client";

import { useState, useRef, useEffect, useCallback } from "react";
import Image from "next/image";
import { useRouter } from "@/i18n/navigation";
import type { Locale } from "@/i18n/routing";

type IndexEntry = {
  slug: string;
  koreanSlug: string;
  titleKo: string;
  titleEn: string;
  tagsKo: string[];
  badgeType: "auspicious" | "inauspicious" | "neutral";
  hero: string | null;
};

type Props = {
  locale: Locale;
  placeholder: string;
  placeholderShort: string;
  buttonLabel: string;
};

const BADGE_STYLES = {
  auspicious: "bg-green-500/20 text-green-300",
  inauspicious: "bg-red-500/20 text-red-300",
  neutral: "hidden",
};

const BADGE_LABELS = {
  auspicious: { ko: "길몽", en: "Auspicious" },
  inauspicious: { ko: "흉몽", en: "Inauspicious" },
  neutral: { ko: "", en: "" },
};

function score(entry: IndexEntry, q: string, locale: Locale): number {
  if (!q) return 0;
  const title = locale === "ko" ? entry.titleKo : entry.titleEn.toLowerCase();
  const qn = locale === "ko" ? q : q.toLowerCase();

  if (title === qn) return 100;
  if (title.startsWith(qn)) return 80;
  if (title.includes(qn)) return 60;
  if (locale === "ko" && entry.tagsKo.some((t) => t === qn)) return 50;
  if (locale === "ko" && entry.tagsKo.some((t) => t.includes(qn))) return 30;
  return 0;
}

export function SearchBar({ locale, placeholder, placeholderShort, buttonLabel }: Props) {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState<IndexEntry[]>([]);
  const [activeIdx, setActiveIdx] = useState(-1);
  const [open, setOpen] = useState(false);
  const router = useRouter();
  const indexRef = useRef<IndexEntry[] | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Lazy-load index on first keystroke
  const loadIndex = useCallback(async () => {
    if (indexRef.current) return;
    const res = await fetch("/search-index.json");
    indexRef.current = await res.json();
  }, []);

  // Search whenever query changes
  useEffect(() => {
    const q = query.trim();
    if (!q || !indexRef.current) {
      setResults([]);
      setOpen(false);
      return;
    }
    const scored = indexRef.current
      .map((e) => ({ entry: e, s: score(e, q, locale) }))
      .filter((x) => x.s > 0)
      .sort((a, b) => b.s - a.s)
      .slice(0, 6)
      .map((x) => x.entry);
    setResults(scored);
    setActiveIdx(-1);
    setOpen(scored.length > 0);
  }, [query, locale]);

  // Click outside to close
  useEffect(() => {
    function onClickOutside(e: MouseEvent) {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setOpen(false);
      }
    }
    document.addEventListener("mousedown", onClickOutside);
    return () => document.removeEventListener("mousedown", onClickOutside);
  }, []);

  function navigate(entry: IndexEntry) {
    const slug = locale === "ko" ? entry.koreanSlug : entry.slug;
    router.push({ pathname: "/dream/[slug]", params: { slug } }, { locale });
    setOpen(false);
    setQuery("");
  }

  function handleChange(e: React.ChangeEvent<HTMLInputElement>) {
    const val = e.target.value;
    setQuery(val);
    if (val.trim()) loadIndex();
  }

  function handleKeyDown(e: React.KeyboardEvent) {
    if (!open) return;
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setActiveIdx((i) => Math.min(i + 1, results.length - 1));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setActiveIdx((i) => Math.max(i - 1, -1));
    } else if (e.key === "Enter") {
      e.preventDefault();
      const target = activeIdx >= 0 ? results[activeIdx] : results[0];
      if (target) navigate(target);
    } else if (e.key === "Escape") {
      setOpen(false);
    }
  }

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (results[0]) navigate(results[activeIdx >= 0 ? activeIdx : 0]);
  }

  const inputClass =
